// ══════════════════════════════════════════════════════════════════
//  CONFIGURE HERE -- change these 4 variables, nothing else
// ══════════════════════════════════════════════════════════════════

// Where to save scraped articles (can be a different repo!)
const OUTPUT_DIR = 'C:\\Users\\Voelt\\ai-dev-starter\\data\\knowledge\\raw\\medium';

// What to scrape -- MODE + SOURCE
//   'list'      + list URL (DEFAULT)
//   'tag'       + tag name (no cookies needed)
//   'article'   + article URL
//   'feed'      + RSS feed URL
//   'bookmarks' + (SOURCE ignored)
const MODE   = 'list';
const SOURCE = 'https://medium.com/@voeltzke.christoph/list/coding-6c7978acb372';
const MAX    = 20;

// ══════════════════════════════════════════════════════════════════
//  Build command (don't edit below)
// ══════════════════════════════════════════════════════════════════
let args;
switch (MODE) {
  case 'list':      args = `--list "${SOURCE}" --max ${MAX}`; break;
  case 'article':   args = `--article "${SOURCE}" --max ${MAX}`; break;
  case 'feed':      args = `--url "${SOURCE}" --max ${MAX}`; break;
  case 'bookmarks': args = `--bookmarks --max ${MAX}`; break;
  default:          args = `--tag "${SOURCE}" --max ${MAX}`; break;
}

args += ` --output "${OUTPUT_DIR}"`;

const command = `cd /d C:\\Users\\Voelt\\ai-dev-starter && .venv\\Scripts\\python.exe -m knowledge.medium_scraper ${args}`;

return [{ json: { command, source: MODE === 'bookmarks' ? 'bookmarks' : SOURCE } }];

const output = $input.first().json.stdout || '';
const exitCode = $input.first().json.exitCode ?? 0;
const source = $items("Configure")[0].json.source || 'unknown';

const savedMatch = output.match(/saved (\d+)\/(\d+)/);
const saved = savedMatch ? parseInt(savedMatch[1]) : null;

const titles = [];
for (const line of output.split('\n')) {
  if (line.includes('[OK] Saved:')) titles.push(line.replace(/.*\[OK\] Saved:/,'').trim());
}

const kbMatch = output.match(/Total articles saved: (\d+)/);
const totalInKb = kbMatch ? parseInt(kbMatch[1]) : null;

const summary = [
  `Status: ${exitCode === 0 ? 'OK' : 'Error (exit ' + exitCode + ')'}`,
  `Source: ${source}`,
  saved !== null ? `Articles fetched: ${saved}` : '',
  totalInKb !== null ? `Total in knowledge base: ${totalInKb}` : '',
  titles.length ? '\nSaved:\n' + titles.map(t => '  - ' + t).join('\n') : ''
].filter(Boolean).join('\n');

return [{ json: { summary, exitCode, titles, saved, totalInKb, rawOutput: output } }];
